type CatalogKind = 'location' | 'organization' | 'item'
type CatalogPool = Partial<Record<CatalogKind, string[]>>
export type CatalogExpansion = { reference: CatalogPool; fictionalComplete: CatalogPool }

const pack = (
  referenceLocation: string[], referenceOrganization: string[], referenceItem: string[],
  fictionalLocation: string[], fictionalOrganization: string[], fictionalItem: string[],
): CatalogExpansion => ({
  reference: { location: referenceLocation, organization: referenceOrganization, item: referenceItem },
  fictionalComplete: { location: fictionalLocation, organization: fictionalOrganization, item: fictionalItem },
})

